import json, sys, traceback
import agentdojo
import agentdojo.attacks
from agentdojo.attacks.attack_registry import ATTACKS
from agentdojo.task_suite.load_suites import get_suites

class StubPipeline:
    name = "gpt-4o-2024-05-13"

suites = get_suites("v1")
out = {}
errs = {}
for attack_name, cls in sorted(ATTACKS.items()):
    if attack_name == "manual":
        continue
    strings = set()
    for suite_name, suite in suites.items():
        try:
            atk = cls(suite, StubPipeline())
        except Exception as exc:
            errs.setdefault(attack_name, []).append(f"{suite_name}: init {type(exc).__name__}: {exc}")
            continue
        for ut in suite.user_tasks.values():
            for it in suite.injection_tasks.values():
                try:
                    d = atk.attack(ut, it)
                except Exception as exc:
                    errs.setdefault(attack_name, []).append(
                        f"{suite_name}/{ut.ID}/{it.ID}: {type(exc).__name__}: {exc}")
                    continue
                strings.update(d.values())
                if getattr(cls, "is_dos_attack", False):
                    break
            if getattr(cls, "is_dos_attack", False):
                break
    out[attack_name] = sorted(strings)
    print(attack_name, len(strings), file=sys.stderr)

json.dump({"version": agentdojo.__version__ if hasattr(agentdojo,'__version__') else None,
           "attacks": out, "errors": errs},
          open("agentdojo_corpus.json", "w", encoding="utf-8"), indent=1, ensure_ascii=False)
print("errors:", {k: len(v) for k, v in errs.items()}, file=sys.stderr)
